'use strict';
const test=require('node:test');const assert=require('node:assert/strict');const fs=require('node:fs');const path=require('node:path');const vm=require('node:vm');
const root=path.resolve(__dirname,'../..'),html=fs.readFileSync(path.join(root,'index.html'),'utf8'),aux=fs.readFileSync(path.join(root,'aux-issue-report.js'),'utf8');
function fragment(from,to){const a=html.indexOf(from),b=html.indexOf(to,a+1);assert(a>=0&&b>a,`Missing boundary ${from}`);return html.slice(a,b);}
function runtime(){
 const ctx={console,location:{pathname:'/PL-Life/'},navigator:{userAgent:'Test Browser',platform:'test',onLine:false},window:{indexedDB:{}},APP_UI_VERSION:'8.1.12.323',DATA_SCHEMA_VERSION:26,Date,Set,Error,TypeError,ReferenceError};
 ctx.sanitizeIssueDiagnosticText=(s)=>String(s||'').replace(/PL收集梦想生活_自动备份_[^\s]+\.zip/g,'[备份文件名已隐藏]').slice(0,6000);
 ctx.issueDiagnosticValue=(txt,label)=>{const m=String(txt||'').match(new RegExp('(?:^|\\n)'+label+'：([^\\n]+)'));return m?m[1]:''};ctx.browserDiagnosticLabel=()=> 'Test (no personal details)';
 vm.createContext(ctx);vm.runInContext(fragment('function plIncidentSafeAtom(', 'function persistIssueReport('),ctx);return ctx;
}
const op=(code,args={})=>runtime().plDiagnoseOperation(code,args);
const excel=fragment('function pcExcelImportFailureDetails(', 'function clearPcExcelImportFailure(');
const batch=fragment('async function pcBatchExcelCommit()', 'function initPcBatchExcelDrop(');
const importBackup=fragment('async function reportBackupImportFailure(', 'els.importFile.addEventListener("change",',);
const backupExport=fragment('async function exportBackup()', 'async function exportCompactBackup()');
const compactExport=fragment('async function exportCompactBackup()', 'function showToast(');
const moduleBridge=fragment('async function runModuleExcelTool(', '/* v130: module -> plans -> module;');
const known=['PC_EXCEL_IMPORT','PC_EXCEL_BATCH','PC_EXCEL_EXPORT','PC_MODULE_EXCEL_BRIDGE','BACKUP_ZIP_EXPORT','BACKUP_COMPACT_EXPORT','BACKUP_ZIP_IMPORT','BACKUP_JSON_IMPORT','STORAGE_DIAGNOSTIC','MODULE_TOOL'];
test('all 10 controlled diagnostic operations map to concrete stable source and expected result',()=>{for(const k of known){const r=op(k,{error:{name:'Error'},operation:'local test'});assert.equal(r.component,k==='PC_MODULE_EXCEL_BRIDGE'?'MODULE_EXCEL_BRIDGE':k);assert.match(r.source,/\w+.*\//);assert.notEqual(r.classification,'UNCLASSIFIED_OPERATION_FAILURE');assert.notEqual(r.expected,'未记录')}});
test('native IndexedDB unreadable is not misclassified as mere Excel parse error',()=>{const r=op('PC_EXCEL_BATCH',{error:{name:'AbortError',plStorageFailure:'browser-database-unreadable',plDbDiagnostic:{transactionError:'NotReadableError'}}});assert.equal(r.classification,'IDB_BACKING_STORE_UNREADABLE');assert.equal(r.component,'PC_EXCEL_BATCH')});
test('no generic catch invents a proved root cause from an Error instance',()=>{const r=op('BACKUP_ZIP_IMPORT',{error:new Error('unrelated input'),writeState:'not-confirmed'});assert.equal(r.classification,'BACKUP_IMPORT_STATE_UNCERTAIN');assert.match(r.unknown,/未确认/);assert.equal(r.writeState,'not-confirmed')});
test('a postcommit incident explicitly distinguishes completed commit from unverified readback',()=>{const r=op('PC_EXCEL_BATCH',{writeState:'committed-readback-unverified',phase:'save verification'});assert.equal(r.writeState,'committed-readback-unverified');assert.equal(r.component,'PC_EXCEL_BATCH')});
test('per-card PC import report contains stable sources and excludes confidential names',()=>{const ctx=runtime();ctx.pcDraft={name:'PRIVATE-PC-A',ownerPlId:'ID'};vm.runInContext(excel.slice(0,excel.indexOf('function showPcExcelImportFailure(')),ctx);const result=ctx.pcExcelImportFailureDetails({name:'private-card-file.xlsx'}, {name:'Error',message:'unusual user private content'}, {name:'PRIVATE-PC-A'}, ctx.pcDraft);assert.match(result.diagnostics,/PC_EXCEL_PARSE_OR_MAPPING_FAILED/);assert.match(result.diagnostics,/importPcExcelFile/);assert.doesNotMatch(result.diagnostics,/PRIVATE-PC-A|private-card-file\.xlsx|unusual user private content/)});
test('PC import failures persist the safe report even when editor inline panel exists',()=>{assert.match(excel,/persistIssueReport\(info\.diagnostics/);assert.match(excel,/incident:info\.incident/)});
test('PC workbook export uses structured incident instead of raw exception popup',()=>{const chunk=fragment('async function pcExportExcelCard(', '/* ---------- PC CoC7 Excel 导入');assert.match(chunk,/plDiagnoseOperation\('PC_EXCEL_EXPORT'/);assert.doesNotMatch(chunk,/appNotice\(`Excel 角色卡导出失败/)});
test('batch import distinguishes postcommit and failed commit in warning',()=>{assert.match(batch,/committed-readback-unverified/);assert.match(batch,/commit-not-confirmed/);assert.match(batch,/unconfirmed-attachments-pending/);assert.match(batch,/plDiagnoseOperation\('PC_EXCEL_BATCH'/)});
test('batch import postcommit branch does not delete its original excel',()=>{const start=batch.indexOf('if(committed){'),end=batch.indexOf('pcs=before;',start);assert(start>=0&&end>start);assert.doesNotMatch(batch.slice(start,end),/pcWorkbookDelete/)});
test('full ZIP backup export records read-only state and controlled source',()=>{assert.match(backupExport,/plDiagnoseOperation\('BACKUP_ZIP_EXPORT'/);assert.match(backupExport,/writeState:'read-only'/);assert.doesNotMatch(backupExport,/diagnostics:`问题编号：BACKUP-EXPORT[^`]*err\?\.stack/)});
test('compact ZIP export never implies original Excel included',()=>{assert.match(compactExport,/plDiagnoseOperation\('BACKUP_COMPACT_EXPORT'/);assert.match(compactExport,/精简备份不包含原始 Excel/)});
test('main backup import does not publish raw stack or personal file name in portable diagnostic',()=>{assert.match(importBackup,/plDiagnoseOperation\('BACKUP_ZIP_IMPORT'/);assert.match(importBackup,/area:'设置 → 数据与备份 → 导入文件'/);assert.doesNotMatch(importBackup,/area:`设置.*\$\{fileName\}/);const arg=importBackup.slice(importBackup.indexOf('showContextIssue({'),importBackup.indexOf('\n}',importBackup.indexOf('showContextIssue({')));assert.doesNotMatch(arg,/JSON\.stringify\(dbDiag\)|err\?\.stack/)});
test('backup transaction statuses remain distinct for protected, committed and rollback',()=>{for(const x of ['protected-transaction-pending','committed-render-failed','verified-rollback','original-data-readback','not-confirmed'])assert.match(importBackup,new RegExp(x))});
test('module bridge covers import and export errors with controlled sources',()=>{assert.match(moduleBridge,/MODULE-EXCEL-BRIDGE-EXPORT/);assert.match(moduleBridge,/MODULE-EXCEL-BRIDGE-IMPORT/);assert.match(moduleBridge,/PC_MODULE_EXCEL_BRIDGE/)});
test('auxiliary module reports classify backup import and reset separately',()=>{const ctx={window:{},document:{},Blob,Date,Set,String,Math,URL};vm.createContext(ctx);vm.runInContext(aux,ctx);let a=ctx.window.PlAuxIssueReport.report({code:'MODULE-BACKUP-IMPORT',state:'可能已经保存',error:{name:'AbortError',message:'private-user.xlsx'}});let b=ctx.window.PlAuxIssueReport.report({code:'MODULE-RESET-FAIL',state:'需要核对',error:{name:'UnknownError'}});assert.match(a,/MODULE_BACKUP_IMPORT_NOT_CONFIRMED/);assert.match(b,/MODULE_RESET_STATE_UNCERTAIN/);assert.doesNotMatch(a,/private-user|\.xlsx/);assert.match(a,/写入与提交/)});
test('storage diagnostic reports stable operation source and no raw error message',()=>{const ctx={window:{},document:{},Blob,Date,Set,String,Math,URL};vm.createContext(ctx);vm.runInContext(aux,ctx);let x=ctx.window.PlAuxIssueReport.report({code:'STORAGE-READ-FAIL',error:{name:'NotReadableError',message:'C:\\private\\file.jpg'}});assert.match(x,/storage-diagnostic.inspectExisting/);assert.match(x,/STORAGE_READ_ONLY_INCOMPLETE/);assert.doesNotMatch(x,/private\\file\.jpg/)});
test('unknown diagnostic code rejected instead of inferred from private error contents',()=>{assert.throws(()=>op('UNREGISTERED_PRIVATE',{error:new Error('credentials')}),/未知的诊断业务编码/)});
test('existing Stage144 structured DB crash helpers remain wired unchanged',()=>{assert.match(html,/function plBuildDiagnosticIncident/);assert.match(html,/IDB_BACKING_STORE_UNREADABLE/);assert.match(html,/function plDiagnosticIncidentLines/);assert.match(html,/function verifyCompleteRestoreAfterReload/)});
